import os
import re
from flask import Flask, request, jsonify
from flask_cors import CORS
from flask_limiter import Limiter
from flask_limiter.util import get_remote_address
import openai
from duckduckgo_search import DDGS

app = Flask(__name__)
CORS(app)

# Rate Limiting: Prevents a single user from exhausting your API credits.
limiter = Limiter(
    get_remote_address,
    app=app,
    default_limits=["100 per day", "10 per hour"],
    storage_uri="memory://",
)

# Load API key from environment variables
openai.api_key = os.getenv("OPENAI_API_KEY")

def sanitize_input(text):
    """Removes potentially harmful characters and limits length."""
    return re.sub(r'[^\w\s,]', '', text).strip()[:50]

def gather_internet_lore(ingredients):
    lore_context = ""
    try:
        with DDGS() as ddgs:
            # Limit to top 2 ingredients for performance and safety
            for ingredient in ingredients[:2]:
                clean_ing = sanitize_input(ingredient)
                query = f"magical folklore and symbolic meaning of {clean_ing}"
                results = list(ddgs.text(query, max_results=2))

                lore_context += f"\nLore for {ingredient}:\n"
                for r in results:
                    # Remove any HTML tags from search snippets
                    snippet = re.sub('<[^<]+?>', '', r['body'])
                    lore_context += f"- {snippet}\n"
    except Exception as e:
        app.logger.error(f"Search error: {e}")
        return "No additional folklore found."
    return lore_context

@app.route('/generate-spell', methods=['POST'])
@limiter.limit("5 per minute")
def generate_spell():
    data = request.json
    raw_ingredients = data.get('ingredients', [])

    if not isinstance(raw_ingredients, list) or not raw_ingredients:
        return jsonify({"error": "No ingredients provided"}), 400

    # Sanitize the list of ingredients
    ingredients = [sanitize_input(str(i)) for i in raw_ingredients[:5]]

    try:
        internet_research = gather_internet_lore(ingredients)

        response = openai.ChatCompletion.create(
            model="gpt-3.5-turbo",
            messages=[
                {"role": "system", "content": "You are a Master of Kitchen Witchery. Create a coherent, poetic spell based on ingredients and provided folklore. Stay safe and mystical."},
                {"role": "user", "content": f"Ingredients: {', '.join(ingredients)}\n\nResearch: {internet_research}"}
            ],
            temperature=0.7,
            max_tokens=400
        )

        spell = response.choices[0].message.content
        return jsonify({"spell": spell})

    except Exception as e:
        app.logger.error(f"Server Error: {e}")
        return jsonify({"error": "The mystical energies are unstable."}), 500

if __name__ == '__main__':
    app.run(debug=False)
